```

### 5.2 Cart Context (context/CartContext.tsx)

```tsx
import { createContext, useContext, useReducer, ReactNode } from 'react';

export interface CartItem {
  productId: string;
  quantity: number;
  price: number;
}

type State = CartItem[];

type Action =
  | { type: 'ADD'; item: CartItem }
  | { type: 'REMOVE'; productId: string }
  | { type: 'UPDATE'; productId: string; quantity: number }
  | { type: 'CLEAR' };

const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'ADD':
      return [...state, action.item];
    case 'REMOVE':
      return state.filter(i => i.productId !== action.productId);
    case 'UPDATE':
      return state.map(i =>
        i.productId === action.productId ? { ...i, quantity: action.quantity } : i
      );
    case 'CLEAR':
      return [];
    default:
      return state;
  }
};

const CartContext = createContext<{
  state: State;
  dispatch: React.Dispatch<Action>;
}>({ state: [], dispatch: () => {} });

export const CartProvider = ({ children }: { children: ReactNode }) => {
  const [state, dispatch] = useReducer(reducer, []);
  return <CartContext.Provider value={{ state, dispatch }}>{children}</CartContext.Provider>;
};

export const useCart = () => useContext(CartContext);
```

### 5.3 Checkout Page (pages/checkout.tsx)

```tsx
import { useCart } from '@/context/CartContext';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import { loadStripe } from '@stripe/stripe-js';

const stripePromise = loadStripe(process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY!);

const schema = z.object({
  name: z.string().min(1),
  email: z.string().email(),
  address: z.string().min(1),
  paymentMethod: z.enum(['card', 'paypal']),
});

export default function Checkout() {
  const { state: cart } = useCart();
  const { register, handleSubmit, formState: { errors } } = useForm({
    resolver: zodResolver(schema),
  });

  const onSubmit = async (data: z.infer<typeof schema>) => {
    const stripe = await stripePromise;
    // Call your backend to create a PaymentIntent
    const res = await fetch('/api/checkout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ cart, ...data }),
    });
    const { clientSecret } = await res.json();

    const result = await stripe?.confirmCardPayment(clientSecret, {
      payment_method: { card: /* card element */ },
    });

    if (result?.error) {
      alert(result.error.message);
    } else {
      alert('Payment successful!');
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="max-w-2xl mx-auto p-4">
      <h1 className="text-2xl font-bold mb-4">Checkout</h1>
      {/* Render cart summary */}
      <div className="mb-4">
        {cart.map(item => (
          <div key={item.productId} className="flex justify-between">
            <span>{item.productId}</span>
            <span>${(item.price * item.quantity).toFixed(2)}</span>
          </div>
        ))}
      </div>
      {/* Billing form */}
      <div className="grid gap-4">
        <input {...register('name')} placeholder="Full Name" className="input" />
        {errors.name && <p className="text-red-600">{errors.name.message}</p>}
        <input {...register('email')} placeholder="Email" className="input" />
        {errors.email && <p className="text-red-600">{errors.email.message}</p>}
        <textarea {...register('address')} placeholder="Address" className="input" />
        {errors.address && <p className="text-red-600">{errors.address.message}</p>}
      </div>
      <button type="submit" className="btn mt-4">Pay Now</button>
    </form>
  );
}
```

